doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doDocumentDetail', {
    DOC_NO: docNo,
    MANAGE_NUMBER: manageNo,
    APPLY_TYPE: "UP"
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);
        var manageNumber = soResult.getArrayMap()[0].MANAGE_NUMBER;
        var docNo = soResult.getArrayMap()[0].DOC_NO;

        $share.data.MANAGE_NUMBER = manageNumber;
        $share.data.DOC_NO = docNo;

        //문서 data mapping
        formObj.dataMapper(soResult);

        doLoadOriginalImg(manageNo + '_' + docNo);

        doLoadChangedImg(manageNo + '_' + docNo);

        var status = soResult.getArrayMap()[0].STATUS;
        $share.data.status = status;
        if (status) {
            setModeByStatus(status);
        } else {
            Alert(Sepoa.cache.text.get('SLM_133.MESSAGE006'), function() { //문서의 상태를 확인할 수 없습니다.
                doBack();
            });
        }
        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});

