gridObj.clearAll();
gridObjView.clearAll();
let mode;
if (applyType == 'UP') {
    mode = 'UPDATE';
} else {
    mode = 'NEW';
}

doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doAppDetail', {
    MANAGE_NUMBER: manageNo,
    VIEW_MODE: mode
}, function(so) {
    if (so.status == 1) {
        var sf = new SepoaFormater(so.result[0]);
        var sfList = sf.getArrayMap();

        if (sf.getRowCount() > 0) {
            for (var i = 0; i < sf.getRowCount(); i++) {
                var maxRowId = dhx4.newId();
                if (status == 'C') {
                    if (sfList[i].CHANGE_FLAG == 'Y' && sfList[i].DEL_FLAG == 'Y') {
                        gridObjView.addRow(maxRowId, '', gridObjView.getRowsNum());
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_ID')).setValue(sfList[i].APP_USER_ID);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_NAME')).setValue(sfList[i].USER_NAME_LOC);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_DEPT')).setValue(sfList[i].APP_USER_DEPT);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_DEPT_NAME')).setValue(sfList[i].DEPT_NAME_LOC);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_SORT')).setValue(sfList[i].APP_SORT);
                    } else {
                        gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_ID')).setValue(sfList[i].APP_USER_ID);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_NAME')).setValue(sfList[i].USER_NAME_LOC);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_DEPT')).setValue(sfList[i].APP_USER_DEPT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_DEPT_NAME')).setValue(sfList[i].DEPT_NAME_LOC);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_SORT')).setValue(sfList[i].APP_SORT);
                    }
                } else {
                    if (sfList[i].CHANGE_FLAG == 'Y' && sfList[i].DEL_FLAG == 'N') {
                        gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_ID')).setValue(sfList[i].APP_USER_ID);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_NAME')).setValue(sfList[i].USER_NAME_LOC);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_DEPT')).setValue(sfList[i].APP_USER_DEPT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_USER_DEPT_NAME')).setValue(sfList[i].DEPT_NAME_LOC);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('APP_SORT')).setValue(sfList[i].APP_SORT);
                    } else if (sfList[i].CHANGE_FLAG == 'N' && sfList[i].DEL_FLAG == 'N') {
                        gridObjView.addRow(maxRowId, '', gridObjView.getRowsNum());
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_ID')).setValue(sfList[i].APP_USER_ID);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_NAME')).setValue(sfList[i].USER_NAME_LOC);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_DEPT')).setValue(sfList[i].APP_USER_DEPT);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_USER_DEPT_NAME')).setValue(sfList[i].DEPT_NAME_LOC);
                        gridObjView.cells(maxRowId, gridObjView.getColIndexById('APP_SORT')).setValue(sfList[i].APP_SORT);
                    }
                }
            }
            gridObj.sortRows(gridObj.getColIndexById('APP_SORT'));
            gridObjView.sortRows(gridObj.getColIndexById('APP_SORT'));
        }

        return true;
    } else {
        Alert(so.message);
        doBack();
        return false;
    }
});


