});


let result = false;
if (formObj.getValue("SEAL_MG_USER_ID") != formObj.getValue("CHANGE_SEAL_MG_USER_ID") ||
    formObj.getValue("SEAL_MG_DEPT") != formObj.getValue("CHANGE_SEAL_MG_DEPT") ||
    formObj.getValue("SUB_MG_USER_ID") != formObj.getValue("CHANGE_SUB_MG_USER_ID") ||
    formObj.getValue("SUB_MG_DEPT") != formObj.getValue("CHANGE_SUB_MG_DEPT") ||
    formObj.getValue("SEAL_USE") != formObj.getValue("CHANGE_SEAL_USE") ||
    formObj.getValue("ELECTRON_FLAG") != formObj.getValue("CHANGE_ELECTRON_FLAG") ||
    formObj.getValue("REAL_FLAG") != formObj.getValue("CHANGE_REAL_FLAG") ||
    formObj.getValue("EXTERNAL_FLAG") != formObj.getValue("CHANGE_EXTERNAL_FLAG") ||
    formObj.getValue("SEAL_CATEGORY") != formObj.getValue("CHANGE_SEAL_CATEGORY") ||
    formObj.getValue("PUBLIC_YN") != formObj.getValue("CHANGE_PUBLIC_YN")) {
    result = true;
}
if (sUtils.workflow.check('US1681189618235') && result == false) {//폼에서 변경사항 없다면 그리드에 변경사항이 있는지 확인
    let basicIdArr = [];
    let basicSortArr = [];

    gridObjView.forEachRowA(function(id) {
       let basicId = gridObjView.cells(id, gridObjView.getColIndexById('APP_USER_ID')).getValue();
       let basicSort = gridObjView.cells(id, gridObjView.getColIndexById('APP_SORT')).getValue();
       basicIdArr.push(basicId);
       basicSortArr.push(basicSort);
    });

	let newIdArr = [];
	let newSortArr = [];

    gridObj.forEachRowA(function(id) {
       let newId = gridObj.cells(id, gridObj.getColIndexById('APP_USER_ID')).getValue();
       let newSort = gridObj.cells(id, gridObj.getColIndexById('APP_SORT')).getValue();
       newIdArr.push(newId);
       newSortArr.push(newSort);
    });

	if(basicIdArr.length != newIdArr.length){
		result = true;
	}else{ // 두 그리드를 비교 첫번째는 id, 두번째는 sort로 비교 변화 없으면 false리턴
		const sameIdArr = basicIdArr.every((value, idx) => value === newIdArr[idx]) 
		if(sameIdArr){
			const sameSortArr = basicSortArr.every((value, idx) => value === newSortArr[idx])	
			if(sameSortArr){
				result = false;
			}else{
				result = true;
			}
		}else{
			result = true;
		}
	}
}

return result;


